async def execute_descriptors(
    function: str | collections.abc.Callable[..., str],
    *positional_args: object,
    args: list[typing.Any] | None = None,
    durations: collections.abc.Callable[..., str],
    duration_values: object | list[typing.Any] | None = None,
    callback: collections.abc.Callable[..., str],
    callback_values: object | list[typing.Any] | None = None,
    callable: collections.abc.Callable[..., str],
    callable_values: object | list[typing.Any] | None = None,
) -> temporalio.workflow.NexusOperationHandle[ExecuteFunctionResult,]:
    """
    Args:
        positional_args: Positional arguments for function. Cannot be set if args is
            set.
        args: List-form arguments for function. Cannot be set if positional_args are
            set. For typed function callables, list contents are not statically
            typechecked; pass function arguments positionally for precise typechecking.
        duration_values: Argument value, or list of argument values, for durations. For
            typed single-argument signals, scalar signal_args values are statically
            typechecked. List-form signal_args values are not precisely typechecked. To
            pass a single signal argument that is itself a list, wrap it in another
            list; otherwise the list is interpreted as multiple signal arguments.
        callback_values: Argument value, or list of argument values, for callback. For
            typed single-argument signals, scalar signal_args values are statically
            typechecked. List-form signal_args values are not precisely typechecked. To
            pass a single signal argument that is itself a list, wrap it in another
            list; otherwise the list is interpreted as multiple signal arguments.
        callable_values: Argument value, or list of argument values, for callable. For
            typed single-argument signals, scalar signal_args values are statically
            typechecked. List-form signal_args values are not precisely typechecked. To
            pass a single signal argument that is itself a list, wrap it in another
            list; otherwise the list is interpreted as multiple signal arguments.
    """
    if positional_args and args is not None:
        raise TypeError("cannot specify both positional arguments and args")
    normalized_args: list[typing.Any] | None = (
        list(positional_args) if positional_args else args
    )
    normalized_duration_values: list[typing.Any] | None
    if duration_values is None:
        normalized_duration_values = None
    elif isinstance(duration_values, list):
        normalized_duration_values = typing.cast(list[typing.Any], duration_values)
    else:
        normalized_duration_values = [duration_values]
    normalized_callback_values: list[typing.Any] | None
    if callback_values is None:
        normalized_callback_values = None
    elif isinstance(callback_values, list):
        normalized_callback_values = typing.cast(list[typing.Any], callback_values)
    else:
        normalized_callback_values = [callback_values]
    normalized_callable_values: list[typing.Any] | None
    if callable_values is None:
        normalized_callable_values = None
    elif isinstance(callable_values, list):
        normalized_callable_values = typing.cast(list[typing.Any], callable_values)
    else:
        normalized_callable_values = [callable_values]
    request = ExecuteDescriptorsRequest(
        function=function,
        args=normalized_args,
        durations=durations,
        duration_values=normalized_duration_values,
        callback=callback,
        callback_values=normalized_callback_values,
        callable=callable,
        callable_values=normalized_callable_values,
    )
    return await _execute_descriptors(request)
